44:function SuspensePage(props: {
45:  children: React.ReactNode;
46:  variant?: Parameters<typeof PageSkeleton>[0]['variant'];
47:  label?: string;
48:}): React.ReactElement {
49:  return (
50:    <SpaErrorBoundary label={props.label || props.variant || 'page'}>
51:      <React.Suspense fallback={<PageSkeleton variant={props.variant || 'default'} />}>
52:        {props.children}
53:      </React.Suspense>
54:    </SpaErrorBoundary>
55:  );
56:}
