export default function DashboardComponent({ props }: IDashboardProps): React.ReactElement {
  const [rows, setRows] = React.useState<any[]>([]);
  const [loading, setLoading] = React.useState(true);

  React.useEffect(() => {
    void loadData();
  }, []);

  const loadData = async () => {
    try {
      const siteUrl =
        props?.Context?.pageContext?.web?.absoluteUrl ||
        props?.siteUrl ||
        '';
      const userId: number = props?.Context?.pageContext?.legacyPageContext?.userId;

      const rootCfg = await loadRootDashboardConfig({
        siteUrl,
        smartMetadataListId: props?.SmartMetadataListID,
      });

      const sites: any[] = rootCfg?.rootSiteData || [];
      const taskFetchStart = moment().subtract(90, 'days').startOf('day').toISOString();
      const filter = `(Modified ge '${taskFetchStart}') and (PercentComplete le 0.90)`;

      const siteResults = await Promise.all(
        sites.map((site: any) =>
          globalCommon.loadAllSiteTaskData(site, filter).catch(() => [] as any[])
        )
      );

      const allTasks: any[] = ([] as any[]).concat(...siteResults);
      const today = moment().format('DD/MM/YYYY');

      const todayTasks = allTasks.filter((item: any) => {
        try {
          const workingAction: any[] = Array.isArray(item.WorkingAction)
            ? item.WorkingAction
            : (globalCommon.parseJSON(item.WorkingAction) || []);
          const workingDetails = workingAction.find((wa: any) => wa.Title === 'WorkingDetails');
          return (
            workingDetails?.InformationData?.some((info: any) =>
              info.WorkingDate === today &&
              Array.isArray(info.WorkingMember) &&
              info.WorkingMember.some((member: any) => member.Id == userId)
            ) ?? false
          );
        } catch {
          return false;
        }
      });

