1:import { spfi, SPFx as spSPFx } from "@pnp/sp";
2:import "@pnp/sp/webs";
3:import "@pnp/sp/lists";
4:import "@pnp/sp/search";
5:
6:const normalizeUrl = (url: any): string =>
7:    (url || "").toString().toLowerCase().replace(/\/+$/, "");
8:
9:// A metadata row is "visible" unless IsVisible is explicitly falsey (false / 0 / "0").
10:// Mirrors the previous drop condition so the pre-checked default matches what used to be shown.
11:const isMetaVisible = (meta: any): boolean =>
12:    !(meta?.IsVisible === false || meta?.IsVisible === 0 || meta?.IsVisible === "0");
13:
14:/**
15: * Build Sites filter UI from SmartMetadata (TaxType Sites / Sites Old).
16: * Groups by Parent.Title (SP / IPPF / mbeon) — same shape as HHHHQA search path.
17: */
18:export function buildActiveSitesFromMetadata(allRootMetaData: any[]): any[] {
19:    const siteItems = (allRootMetaData || []).filter((meta: any) => {
20:        if (!meta) return false;
21:        const tax = meta.TaxType;
22:        if (tax !== "Sites" && tax !== "Sites Old") return false;
23:        // Non-visible sites are now LISTED (unchecked by default) rather than dropped (q-nonvisible = show-unchecked).
24:        return Boolean(meta.listId && meta.Title);
25:    });
26:
27:    const grouped: Record<string, any> = {};
28:    siteItems.forEach((meta: any) => {
29:        const groupTitle = meta?.Parent?.Title || meta?.siteName || meta?.Title || "Sites";
30:        const key = String(groupTitle).toLowerCase();
31:        const siteUrl = meta.originalSiteUrl || meta.siteUrl || "";
32:        if (!grouped[key]) {
33:            grouped[key] = {
34:                Site: {
35:                    Title: groupTitle,
36:                    Url: siteUrl,
37:                    SiteId: meta.SiteId || "",
38:                    WebId: meta.WebId || "",
39:                    IsVisible: false
40:                },
41:                TaskLists: [] as any[]
42:            };
43:        } else if (siteUrl && !grouped[key].Site.Url) {
44:            grouped[key].Site.Url = siteUrl;
45:        }
46:
47:        // A site is visible (pre-checked by default) if any of its metadata rows is visible.
48:        if (isMetaVisible(meta)) grouped[key].Site.IsVisible = true;
49:
50:        const already = grouped[key].TaskLists.some(
51:            (t: any) =>
52:                (t.Id && meta.listId && t.Id.toLowerCase() === meta.listId.toLowerCase()) ||
53:                (t.Title && meta.Title && t.Title.toLowerCase() === meta.Title.toLowerCase())
54:        );
55:        if (already) return;
56:
57:        const coverObj =
58:            meta?.Item_x005F_x0020_Cover ||
59:            meta?.Item_x0020_Cover ||
60:            meta?.coverImage ||
61:            null;
62:
63:        grouped[key].TaskLists.push({
64:            Title: meta.Title,
65:            Id: meta.listId,
66:            Url: siteUrl
67:                ? `${siteUrl.replace(/\/+$/, "")}/Lists/${encodeURIComponent(meta.Title)}`
68:                : "",
69:            Item_x005F_x0020_Cover: coverObj,
70:            Item_x0020_Cover: coverObj,
71:            coverImage: coverObj
72:        });
73:    });
74:
75:    return Object.keys(grouped)
76:        .map((k) => grouped[k])
77:        .filter((g) => g.TaskLists?.length > 0);
78:}
79:
80:async function getFilteredTaskLists(activeSites: any, allRootMetaData: any) {
81:    const result: any = [];
82:    activeSites?.forEach((siteObj: any) => {
83:        const siteUrlNorm = normalizeUrl(siteObj.Site?.Url);
84:        const matchingRootItems = (allRootMetaData || []).filter((meta: any) => {
85:            if (!meta) return false;
86:            const metaUrlNorm = normalizeUrl(meta.siteUrl || meta.originalSiteUrl);
87:            return Boolean(metaUrlNorm && siteUrlNorm && metaUrlNorm === siteUrlNorm);
88:        });
89:
90:        if (!matchingRootItems.length) return;
91:
92:        const matchedTaskLists: any = [];
93:        siteObj?.TaskLists?.forEach((taskList: any) => {
94:            const matchedMeta = matchingRootItems.find((meta: any) => {
95:                if (meta.listId && taskList.Id && meta.listId.toLowerCase() === String(taskList.Id).toLowerCase()) {
96:                    return true;
97:                }
98:                return Boolean(
99:                    meta.Title &&
100:                    taskList.Title &&
101:                    meta.Title.toLowerCase() === String(taskList.Title).toLowerCase()
102:                );
103:            });
104:            if (matchedMeta) {
105:                const coverObj =
106:                    matchedMeta.Item_x005F_x0020_Cover ||
107:                    matchedMeta.Item_x0020_Cover ||
108:                    matchedMeta.coverImage ||
109:                    null;
110:                matchedTaskLists.push({
111:                    ...taskList,
112:                    Item_x005F_x0020_Cover: coverObj,
113:                    Item_x0020_Cover: coverObj,
114:                    coverImage: coverObj
115:                });
116:            }
117:        });
118:
119:        if (matchedTaskLists.length > 0) {
120:            // Join IsVisible from the matching metadata rows so the search path carries the flag too
121:            // (q-buildpath = both-enrich). Preserve any IsVisible already set upstream.
122:            const siteVisible = siteObj.Site?.IsVisible === true || matchingRootItems.some(isMetaVisible);
123:            result.push({
124:                Site: { ...siteObj.Site, IsVisible: siteVisible },
125:                TaskLists: matchedTaskLists
126:            });
127:        }
128:    });
129:    return result;
130:}
