132:export async function getSubsitesForRoot({ spContext, AllRootMetaData }: any) {
133:    if (!spContext) {
134:        console.error("[FetchDynamicActiveSites] Missing SPFx context");
135:        return buildActiveSitesFromMetadata(AllRootMetaData);
136:    }
137:
138:    const sp = spfi().using(spSPFx(spContext));
139:    const rawUrl =
140:        spContext?.pageContext?.web?.absoluteUrl ||
141:        (typeof window !== "undefined" ? window.location.href : "");
142:    const rootUrl = rawUrl
143:        ? rawUrl.match(/^(https?:\/\/[^\/]+\/sites\/[^\/\?#]+)/i)?.[1] ||
144:        rawUrl.replace(/\/+$/, "")
145:        : "https://hhhhteams.sharepoint.com/sites/HHHH";
146:
147:    // Step 1: Get webs under the site collection (HHHHQA parity)
148:    let subsites: any[] = [];
149:    try {
150:        const subsiteResults = await sp.search({
151:            Querytext: `Path:${rootUrl}* contentclass:STS_Web`,
152:            RowLimit: 100,
153:            SelectProperties: ["Title", "Path", "SiteId", "WebId"]
154:        });
155:        subsites = (subsiteResults?.PrimarySearchResults || []).map((r: any) => ({
156:            Title: r.Title,
157:            Url: r.Path,
158:            SiteId: r.SiteId,
159:            WebId: r.WebId
160:        }));
161:    } catch (err) {
162:        console.error("[FetchDynamicActiveSites] Error searching subsites:", err);
163:    }
164:
165:    // Also include unique siteUrls from Sites metadata (covers webs search may miss)
166:    const urlSet = new Set(subsites.map((s) => normalizeUrl(s.Url)));
167:    (AllRootMetaData || []).forEach((meta: any) => {
168:        if (
169:            (meta?.TaxType === "Sites" || meta?.TaxType === "Sites Old") &&
170:            meta?.siteUrl &&
171:            !urlSet.has(normalizeUrl(meta.siteUrl))
172:        ) {
173:            urlSet.add(normalizeUrl(meta.siteUrl));
174:            subsites.push({
175:                Title: meta?.Parent?.Title || meta?.siteName || meta?.Title,
176:                Url: meta.siteUrl,
177:                SiteId: "",
178:                WebId: ""
179:            });
180:        }
181:    });
182:
183:    // Step 2: For each web, fetch Task lists (BaseTemplate 171 — HHHHQA parity)
184:    const siteTasks = await Promise.all(
185:        subsites.map(async (site) => {
186:            try {
187:                const siteSp = spfi(site.Url).using(spSPFx(spContext));
188:                const lists = await siteSp.web.lists();
189:                const taskLists = lists?.filter((l: any) => l.BaseTemplate === 171);
190:                const excludedTitles: string[] = [
191:                    "Offshore Tasks",
192:                    "Master Tasks",
193:                    "DRR",
194:                    "SDC Sites",
195:                    "QA",
196:                    "Foundation",
197:                    "Health",
198:                    "Gender",
199:                    "SP Online"
200:                ];
201:                const activeTaskList = taskLists?.filter(
202:                    (taskList: any) =>
203:                        taskList?.Title !== undefined && !excludedTitles.includes(taskList.Title)
204:                );
205:                // Enrich the search-built site with IsVisible joined from Sites metadata (q-buildpath = both-enrich).
206:                const siteUrlNorm = normalizeUrl(site.Url);
207:                const siteIsVisible = (AllRootMetaData || []).some(
208:                    (meta: any) =>
209:                        (meta?.TaxType === "Sites" || meta?.TaxType === "Sites Old") &&
210:                        normalizeUrl(meta.siteUrl || meta.originalSiteUrl) === siteUrlNorm &&
211:                        isMetaVisible(meta)
212:                );
213:                return {
214:                    Site: { ...site, IsVisible: siteIsVisible },
215:                    TaskLists: activeTaskList?.map((l: any) => ({
216:                        Title: l.Title,
217:                        Id: l.Id,
218:                        Url: `${site.Url}/Lists/${encodeURIComponent(l.Title)}`
219:                    }))
220:                };
221:            } catch (e) {
222:                console.log(`Error fetching lists for ${site.Url}`, e);
223:                return { Site: site, TaskLists: [] };
224:            }
225:        })
226:    );
227:
228:    const AllRootSites = (AllRootMetaData || []).filter(
229:        (root: any) => root?.TaxType === "Sites" || root?.TaxType === "Sites Old"
230:    );
231:    const activesitesTasks = siteTasks?.filter((e) => e.TaskLists?.length > 0);
232:    let activeTAsklist = await getFilteredTaskLists(activesitesTasks, AllRootSites);
233:
234:    // Prefer search+list path when it produced sites (HHHHQA behavior)
235:    if (activeTAsklist?.length > 0) {
236:        return activeTAsklist;
237:    }
238:
239:    // Reliable fallback: SmartMetadata Sites grouped like the working QA UI
240:    const fromMeta = buildActiveSitesFromMetadata(AllRootMetaData);
241:    if (fromMeta.length > 0) {
242:        return fromMeta;
243:    }
244:
245:    return activeTAsklist || [];
246:}

